cd /mnt/c/Projects/biotech_screener/biotech-screener && python3 << 'EOF'
import json
from pathlib import Path

with open('docs/hermes_skills/_meta.json') as f:
    meta = json.load(f)

print("HERMES SKILLS AUDIT (2026-06-19)")
print("=" * 80)
print(f"\nTotal skills: {len(meta['skills'])}")
print(f"Last registry update: {meta['last_updated']}")

# Check for missing documentation
skills_dir = Path('docs/hermes_skills')
missing_docs = []
for skill_name, skill_meta in meta['skills'].items():
    skill_file = skill_meta.get('file')
    if skill_file:
        full_path = skills_dir / skill_file
        if not full_path.exists():
            missing_docs.append((skill_name, skill_file))

print(f"\nDocumentation Status:")
print(f"  Documented: {len(meta['skills']) - len(missing_docs)}/{len(meta['skills'])}")
if missing_docs:
    print(f"  Missing documentation:")
    for name, file in missing_docs:
        print(f"    - {name} (expected: {file})")
else:
    print(f"  ✅ All skills have documentation")

# Check source distribution
by_source = {}
for name, meta_item in meta['skills'].items():
    source = meta_item.get('source', 'unknown')
    by_source[source] = by_source.get(source, 0) + 1

print(f"\nSource Distribution:")
for source, count in sorted(by_source.items()):
    print(f"  {source}: {count}")

# Check for skills in filesystem that aren't registered
print(f"\nFilesystem vs Registry Check:")
skill_dirs = list(Path('skills').glob('*/'))
registered_cursor_skills = {
    s: m for s, m in meta['skills'].items() 
    if m.get('source') == 'cursor_skill'
}
filesystem_names = {d.name for d in skill_dirs if d.is_dir()}
print(f"  Filesystem skill directories: {len(filesystem_names)}")
print(f"  Registered cursor_skill entries: {len(registered_cursor_skills)}")

unregistered = filesystem_names - {
    m.get('source_authority', '').replace('skills/', '').replace('/SKILL.md', '')
    for m in meta['skills'].values()
    if m.get('source') == 'cursor_skill'
}
if unregistered:
    print(f"  ⚠️  Unregistered skills in filesystem: {unregistered}")
else:
    print(f"  ✅ All filesystem skills are registered")

EOF

